@if($priced)<fieldset><legend>Price ({{ $currency['code']??'MYR' }})</legend><input type="hidden" name="price_filter" :value="priceChanged?'1':'0'"><input type="hidden" name="min_price" :value="min"><input type="hidden" name="max_price" :value="max"><div class="wd-filter-price"><label>Min<input type="number" step="0.01" min="0" aria-label="Minimum price amount" value="{{ number_format($filters['minPrice']/100*($currency['exchangeRate']??1),$currency['decimalPlaces']??2,'.','') }}" @change="min=Math.max(@js($facets['priceBounds']['min']),Math.min(max,Math.round(Number($el.value)/rate*100)));priceChanged=true;$el.value=(min/100*rate).toFixed(decimals)"></label><label>Max<input type="number" step="0.01" min="0" aria-label="Maximum price amount" value="{{ number_format($filters['maxPrice']/100*($currency['exchangeRate']??1),$currency['decimalPlaces']??2,'.','') }}" @change="max=Math.min(@js($facets['priceBounds']['max']),Math.max(min,Math.round(Number($el.value)/rate*100)));priceChanged=true;$el.value=(max/100*rate).toFixed(decimals)"></label></div></fieldset>@endif
