@if($facets['hasRatings'])<fieldset><legend>Customer rating</legend><label><input type="radio" name="min_rating" value="0" @checked(!$filters['minRating'])>All ratings</label>@foreach($facets['ratings'] as $facet)<label><input type="radio" name="min_rating" value="{{ $facet['value'] }}" @checked((float)$filters['minRating']===(float)$facet['value'])><span>{{ $facet['label'] }}</span><small>{{ $facet['count'] }}</small></label>@endforeach</fieldset>@endif
